.scholar-exam-paper .inline-title { display: none; }
.scholar-exam-paper .metadata-container { display: none; }
.scholar-exam-paper .callout[data-callout="question"] { margin-block-start: 2.4rem; }
.scholar-exam-paper .contains-task-list { padding-inline-start: 0; }
.scholar-exam-paper .task-list-item {
  list-style: none;
  border: 1px solid var(--background-modifier-border);
  border-radius: 0.55rem;
  padding: 0.8rem 1rem 0.8rem 2.6rem;
  margin-block: 0.55rem;
  background: var(--background-primary);
}
.scholar-exam-paper .task-list-item-checkbox { margin-inline-start: -1.7rem; margin-inline-end: 0.6rem; cursor: pointer; }
.scholar-exam-paper .task-list-item:hover { border-color: var(--text-accent); }
.scholar-exam-paper .task-list-item.is-checked,
.scholar-exam-paper .task-list-item.is-checked :is(p, strong, em, span) {
  color: var(--text-normal);
  text-decoration: none;
  opacity: 1;
}
.scholar-exam-paper .task-list-item.is-checked {
  border-color: var(--interactive-accent);
  background: color-mix(in srgb, var(--interactive-accent) 10%, var(--background-primary));
}
.scholar-exam-paper .callout[data-callout="question"] .task-list-item { padding: 0.65rem 0.8rem 0.65rem 2.2rem; }
.scholar-exam-paper .HyperMD-task-line[data-task="x"] { color: var(--text-normal); text-decoration: none; }

/* Hide internal identifiers, not useful status/progress or the stored metadata. */
.scholar-note .metadata-property:is(
  [data-property-key="book_id"], [data-property-key="chapter_id"],
  [data-property-key="section_id"], [data-property-key="exam_id"],
  [data-property-key="tutor_id"], [data-property-key="type"],
  [data-property-key="cssclasses"], [data-property-key="book_instance_id"],
  [data-property-key="form_fingerprint"], [data-property-key="answer_format"]
) { display: none; }

/* ---- Narrow screens & print ---- */
@media (max-width: 640px) {
  .scholar-note :is(th, td) { padding: 0.65em 0.5em; }
  .scholar-note .callout { padding: 0.75rem; }
  .scholar-note:is(.scholar-book, .scholar-chapter) td:first-child { white-space: normal; }
}

@media print {
  .scholar-note .callout.is-collapsible .callout-content { display: block !important; }
  .scholar-note .callout { break-inside: avoid; }
  /* A figure frame is atomic on paper too. */
  .scholar-note .callout[data-callout="scholar-figure"] :is(img, .image-embed) { break-inside: avoid; }
}

@media (prefers-reduced-motion: reduce) {
  .scholar-note .scholar-progress span { transition: none; }
}

