.scholar-note {
  /* One spacing step for every gap Scholar draws: callouts, headings, lesson units. */
  --scholar-space-1: 0.4rem;
  --scholar-space-2: 0.8rem;
  --scholar-space-3: 1.2rem;
  --scholar-space-4: 1.6rem;
  --file-line-width: 78ch;
  --line-height-normal: 1.65;
  --table-border-color: var(--background-modifier-border);
  --table-header-background: var(--background-secondary);
  --table-header-color: var(--text-muted);
  --table-row-background-hover: var(--background-secondary);
  color: var(--text-normal);
}

/* ---- Headings & prose ---- */
.scholar-note :is(h2, .HyperMD-header-2) {
  margin-block-start: 2em;
  padding-block-end: 0.45em;
  border-bottom: 1px solid var(--background-modifier-border);
  font-size: 1.12em;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.scholar-note h3 {
  margin-block-start: 1.6em;
  font-size: 1em;
  font-weight: 650;
}

.scholar-note :is(p, li) { line-height: 1.65; }
.scholar-note li + li { margin-block-start: 0.4em; }
.scholar-note a.internal-link { text-decoration-thickness: 1px; text-underline-offset: 0.2em; }

/* Lesson units: an `---` rule and the heading that follows it share one step. */
.scholar-note hr { margin-block: var(--scholar-space-4); border: 0; border-top: 1px solid var(--background-modifier-border); }
