.scholar-note .callout[data-callout="question"] {
  background: color-mix(in srgb, var(--interactive-accent) 4%, var(--background-primary));
  margin-block: 1.6rem;
}
.scholar-note .callout[data-callout="question"] > .callout-title { font-size: 0.9em; color: var(--text-accent); }
.scholar-note .callout[data-callout="question"] h4 {
  font-size: 0.78em;
  font-weight: 600;
