/* Scholar built-in note styling. Managed by Scholar; use another snippet for overrides.
   Self-contained: every colour resolves through var(…) or color-mix(in srgb, …) so the
   stylesheet reads correctly in light, dark and print. */

/* ---- Scale & base ---- */
.scholar-note {
  /* One spacing step for every gap Scholar draws: callouts, headings, lesson units. */
  --scholar-space-1: 0.4rem;
  --scholar-space-2: 0.8rem;
  --scholar-space-3: 1.2rem;
  --scholar-space-4: 1.6rem;
  --file-line-width: 78ch;
  --line-height-normal: 1.65;
  --table-border-color: var(--background-modifier-border);
  --table-header-background: var(--background-secondary);
  --table-header-color: var(--text-muted);
  --table-row-background-hover: var(--background-secondary);
  color: var(--text-normal);
}

/* ---- Headings & prose ---- */
.scholar-note :is(h2, .HyperMD-header-2) {
  margin-block-start: 2em;
  padding-block-end: 0.45em;
  border-bottom: 1px solid var(--background-modifier-border);
  font-size: 1.12em;
  font-weight: 650;
  letter-spacing: -0.01em;
}

.scholar-note h3 {
  margin-block-start: 1.6em;
  font-size: 1em;
  font-weight: 650;
}

.scholar-note :is(p, li) { line-height: 1.65; }
.scholar-note li + li { margin-block-start: 0.4em; }
.scholar-note a.internal-link { text-decoration-thickness: 1px; text-underline-offset: 0.2em; }

/* Lesson units: an `---` rule and the heading that follows it share one step. */
.scholar-note hr { margin-block: var(--scholar-space-4); border: 0; border-top: 1px solid var(--background-modifier-border); }
.scholar-note .callout + :is(h2, h3) { margin-block-start: var(--scholar-space-4); }

/* ---- Callouts ---- */
.scholar-note .callout {
  border: 1px solid var(--background-modifier-border);
  border-radius: 0.65rem;
  padding: clamp(0.85rem, 3%, 1.3rem);
  margin-block: 1.35rem;
  background: var(--background-secondary);
  color: var(--text-normal);
  box-shadow: none;
  overflow-wrap: anywhere;
}

.scholar-note .callout-title { color: var(--text-normal); font-weight: 650; gap: 0.6em; }
.scholar-note .callout-content { color: var(--text-normal); }
.scholar-note .callout-content > :last-child { margin-block-end: 0; }
.scholar-note .callout-content > :first-child { margin-block-start: 0.6em; }
.scholar-note .callout[data-callout="info"] { border-inline-start: 3px solid var(--interactive-accent); }
.scholar-note .callout[data-callout="tip"] { border-inline-start: 3px solid var(--text-accent); }
.scholar-note .callout[data-callout="success"] { border-inline-start: 3px solid var(--text-success); }
.scholar-note .callout[data-callout="warning"] { border-inline-start: 3px solid var(--text-warning); }
.scholar-note .callout[data-callout="question"] { border-inline-start: 3px solid var(--text-accent); }
.scholar-note .callout[data-callout="failure"] { border-inline-start: 3px solid var(--text-error); }
.scholar-note .callout.is-collapsed { background: transparent; }
.scholar-note .callout.is-collapsed .callout-title { color: var(--text-muted); }
.scholar-note .callout .callout { margin-block: 0.85rem; }

/* Questions, equations, and their visuals are complete reading units. */
.scholar-note .callout[data-callout="question"] {
  background: color-mix(in srgb, var(--interactive-accent) 4%, var(--background-primary));
  margin-block: 1.6rem;
}
.scholar-note .callout[data-callout="question"] > .callout-title { font-size: 0.9em; color: var(--text-accent); }
.scholar-note .callout[data-callout="question"] h4 {
  font-size: 0.78em;
  font-weight: 600;
  color: var(--text-muted);
  letter-spacing: 0.035em;
  margin-block: 1rem 0.5rem;
}
.scholar-note .callout[data-callout="question"] ol { padding-inline-start: 1.5em; }
.scholar-note .callout[data-callout="question"] ol > li { padding-inline-start: 0.35em; margin-block: 0.6em; }
.scholar-note .callout[data-callout="success"] {
  border-inline-start-color: var(--text-success, var(--color-green));
  background: color-mix(in srgb, var(--color-green) 5%, var(--background-primary));
}
.scholar-note .callout[data-callout="warning"] {
  border-inline-start-color: var(--text-warning, var(--color-orange));
  background: color-mix(in srgb, var(--color-orange) 5%, var(--background-primary));
}
.scholar-note .callout[data-callout="note"] .math-block { font-size: 1.08em; }
.scholar-note .callout.is-collapsed {
  padding: 0.4rem 0;
  border: 0;
  border-top: 1px solid var(--background-modifier-border);
  border-radius: 0;
  margin-block: 0.8rem;
}
.scholar-note .callout.is-collapsed > .callout-title { font-size: 0.82em; font-weight: 500; }

/* ---- Scholar callouts: status, equation, figure ---- */

/* Status header: metadata, not a headline — it sits above the first heading
   without competing with it. */
.scholar-note .callout[data-callout="scholar-status"] {
  margin-block: var(--scholar-space-1) var(--scholar-space-2);
  padding: var(--scholar-space-2);
  border-radius: 0.55rem;
  background: color-mix(in srgb, var(--background-secondary) 70%, transparent);
  font-size: 0.86em;
}
.scholar-note .callout[data-callout="scholar-status"] .callout-icon { display: none; }
.scholar-note .callout[data-callout="scholar-status"] > .callout-title { gap: 0; color: var(--text-muted); font-size: 1em; font-weight: 500; }
.scholar-note .callout[data-callout="scholar-status"] .callout-content { color: var(--text-muted); }
.scholar-note .callout[data-callout="scholar-status"] .callout-content > p { margin-block: 0; }
.scholar-note .callout[data-callout="scholar-status"] + :is(h2, h3) { margin-block-start: var(--scholar-space-3); }

/* Key equation: the section's anchor — accent-marked, generous, centred maths,
   a scannable symbol list and a muted provenance line. */
.scholar-note .callout[data-callout="scholar-equation"] {
  --callout-icon: sigma;
  border-inline-start: 3px solid var(--interactive-accent);
  background: color-mix(in srgb, var(--interactive-accent) 5%, var(--background-primary));
  padding: var(--scholar-space-3) var(--scholar-space-3) var(--scholar-space-2);
  margin-block: var(--scholar-space-3);
}
.scholar-note .callout[data-callout="scholar-equation"] > .callout-title { color: var(--text-accent); font-size: 0.85em; font-weight: 600; letter-spacing: 0.02em; }
.scholar-note .callout[data-callout="scholar-equation"] .math-block { text-align: center; margin-inline: auto; font-size: 1.12em; }
.scholar-note .callout[data-callout="scholar-equation"] .callout-content > p > strong:first-child {
  color: var(--text-muted);
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.03em;
}
.scholar-note .callout[data-callout="scholar-equation"] .callout-content ul {
  list-style: none;
  padding-inline-start: 0;
  margin-block: var(--scholar-space-1) var(--scholar-space-2);
}
.scholar-note .callout[data-callout="scholar-equation"] .callout-content ul > li {
  margin-block: 0;
  padding-block: var(--scholar-space-1);
  padding-inline-start: 0;
  line-height: 1.45;
}
.scholar-note .callout[data-callout="scholar-equation"] .callout-content ul > li + li {
  border-block-start: 1px solid color-mix(in srgb, var(--background-modifier-border) 60%, transparent);
}
.scholar-note .callout[data-callout="scholar-equation"] .callout-content > p:last-child {
  color: var(--text-muted);
  font-size: 0.82em;
}

/* Source figure: framed image, caption in body text, provenance muted. */
.scholar-note .callout[data-callout="scholar-figure"] {
  --callout-icon: image;
  background: var(--background-secondary);
  padding: var(--scholar-space-2) var(--scholar-space-3) var(--scholar-space-3);
  margin-block: var(--scholar-space-3);
}
.scholar-note .callout[data-callout="scholar-figure"] > .callout-title {
  color: var(--text-muted);
  font-size: 0.85em;
  font-weight: 600;
  letter-spacing: 0.02em;
}
.scholar-note .callout[data-callout="scholar-figure"] .image-embed {
  border: 1px solid var(--background-modifier-border);
  border-radius: 0.6rem;
  background: var(--background-secondary);
  padding: var(--scholar-space-2);
  margin-block: var(--scholar-space-2) var(--scholar-space-1);
}
.scholar-note .callout[data-callout="scholar-figure"] .image-embed img {
  border-radius: 0.4rem;
  margin-inline: auto;
}
.scholar-note .callout[data-callout="scholar-figure"] .callout-content > p { color: var(--text-normal); }
.scholar-note .callout[data-callout="scholar-figure"] .callout-content > p:last-child {
  color: var(--text-muted);
  font-size: 0.82em;
}

/* ---- Progress bar & score chip ---- */
.scholar-note .scholar-progress {
  width: 100%;
  height: 0.4rem;
  margin-block: var(--scholar-space-1) 0;
  border-radius: 999px;
  background: var(--background-modifier-border);
  overflow: hidden;
}
.scholar-note .scholar-progress > span {
  display: block;
  width: var(--scholar-progress, 0%);
  height: 100%;
  border-radius: inherit;
  background: var(--interactive-accent);
  transition: width 200ms ease;
}
.scholar-note .scholar-score {
  display: inline-block;
  padding: 0.1em 0.45em;
  border-radius: 0.4em;
  background: color-mix(in srgb, var(--interactive-accent) 15%, transparent);
  color: var(--text-accent);
  font-size: 0.88em;
  font-weight: 650;
  font-variant-numeric: tabular-nums;
  line-height: 1.4;
  white-space: nowrap;
}

/* ---- Tables ---- */
.scholar-note .el-table { overflow-x: auto; }
.scholar-note table { width: 100%; border-collapse: collapse; font-size: 0.92em; }
.scholar-note :is(th, td) { padding: 0.7em 0.85em; vertical-align: top; border-inline: none; }
.scholar-note th { font-size: 0.8em; font-weight: 600; letter-spacing: 0.04em; }
.scholar-note :is(th:first-child, td:first-child) { padding-inline-start: 0.65em; }
.scholar-note :is(th:last-child, td:last-child) { padding-inline-end: 0.65em; }
.scholar-note :is(.table-wrapper, .cm-table-widget) { max-width: 100%; overflow-x: auto; }
.scholar-note:is(.scholar-book, .scholar-chapter) td:first-child { color: var(--text-muted); font-size: 0.85em; white-space: nowrap; }
.scholar-note:is(.scholar-book, .scholar-chapter) tr:has(td:first-child strong) {
  background: color-mix(in srgb, var(--interactive-accent) 9%, var(--background-primary));
}
.scholar-note:is(.scholar-book, .scholar-chapter) td:first-child strong {
  color: var(--text-accent);
  border-radius: 0.35em;
  padding: 0.2em 0.4em;
  background: color-mix(in srgb, var(--interactive-accent) 10%, transparent);
}

/* ---- Figures, maths & code ---- */
.scholar-note img { display: block; max-width: 100%; height: auto; margin-inline: auto; }
.scholar-note .image-embed { display: block; max-width: 100%; margin: 1.25rem auto; }
.scholar-note:is(.scholar-section, .scholar-tutor) { --file-line-width: 74ch; }
.scholar-note:is(.scholar-section, .scholar-tutor) .image-embed {
  width: auto;
  margin-block: 1rem;
}
.scholar-note:is(.scholar-section, .scholar-tutor) .image-embed img {
  max-height: none;
  object-fit: contain;
}
.scholar-note:is(.scholar-section, .scholar-tutor) .callout.is-collapsed {
  padding: 0.4rem 0;
}
.scholar-note .callout[data-callout="example"] { padding: 1rem 1.2rem; }
.scholar-note .callout[data-callout="example"] em { color: var(--text-muted); font-size: 0.9em; }
.scholar-note :is(.math-block, .mermaid) { max-width: 100%; overflow-x: auto; padding-block: 0.75rem; }
.scholar-note .mermaid { text-align: center; }
.scholar-note .mermaid svg { display: block; margin-inline: auto; }
.scholar-note pre { max-width: 100%; overflow-x: auto; border: 1px solid var(--background-modifier-border); border-radius: 0.5rem; }

/* ---- Artifact layouts ---- */

/* Home is a hub: a wider measure, roomier sections, quiet tables. */
.scholar-home { --file-line-width: 84ch; }
