.scholar-note img { display: block; max-width: 100%; height: auto; margin-inline: auto; }
.scholar-note .image-embed { display: block; max-width: 100%; margin: 1.25rem auto; }
.scholar-note:is(.scholar-section, .scholar-tutor) { --file-line-width: 74ch; }
.scholar-note:is(.scholar-section, .scholar-tutor) .image-embed {
  width: auto;
