function parse(text){
  const clean = text.replace(/\/\*[\s\S]*?\*\//g, "");
  const rules = [];
  let buf = "", ctx = [], cur = null;
  for (const ch of clean){
    if (ch === "{"){
      const prelude = buf.trim();
      buf = "";
      if (prelude.startsWith("@")) { ctx.push(prelude); cur = null; }
      else { cur = { media: ctx.slice(-1)[0] || "", selector: prelude.replace(/\s+/g," ").trim(), decls: [] }; }
    } else if (ch === "}"){
      buf = "";
      if (cur){ rules.push(cur); cur = null; } else { ctx.pop(); }
    } else {
      if (cur) cur.decls.push(ch);
      else buf += ch;
    }
  }
  for (const r of rules) r.decls = r.decls.join("").replace(/\s+/g," ").trim();
