const res = await tab.run(async ({ page }) => {
  const css = await Bun.file("C:/Users/basam/.pi/agent/extensions/scholar/scholar.css").text();
  return await page.evaluate((text) => {
    const style = document.createElement("style");
    style.textContent = text;
    document.head.appendChild(style);
    const sheet = style.sheet;
    const top = [...sheet.cssRules];
    const media = top.filter((r) => r.type === 4).map((r) => ({ cond: r.conditionText, n: r.cssRules.length }));
    const parseErrors = [];
    // Any rule Chromium refused to parse would shrink the child list; report totals per media.
    for (const m of media) for (const inner of [...m.cssRules]) if (!inner.selectorText && inner.type !== 4) parseErrors.push(String(inner.cssText).slice(0, 60));
    return { topLevel: top.length, plainRules: top.filter((r) => r.type === 1).length, media, parseErrors };
  }, css);
});
display(res);

