const out = await tab.run(async ({ page }) => {
  const css = await Bun.file("C:/Users/basam/.pi/agent/extensions/scholar/scholar.css").text();
  return await page.evaluate((text) => {
    const style = document.createElement("style");
    style.textContent = text;
    document.head.appendChild(style);
    const flat = [];
    const walk = (rules, media) => {
      for (let i = 0; i < rules.length; i++) {
        const r = rules[i];
        if (r.type === 4) walk(r.cssRules, (media ? media + " && " : "") + r.conditionText);
        else if (r.type === 1) flat.push({ media: media || "", selector: r.selectorText, empty: [] });
      }
    };
    walk(style.sheet.cssRules, "");
    // second pass: for each flat rule, read back every declaration's value
    const probes = [];
    const walk2 = (rules, media) => {
      let k = 0;
      const inner = [];
      for (let i = 0; i < rules.length; i++) {
        const r = rules[i];
        if (r.type === 4) inner.push(...walk2(r.cssRules, (media ? media + " && " : "") + r.conditionText));
        else if (r.type === 1) inner.push({ media: media || "", selector: r.selectorText, style: r.style });
      }
      return inner;
    };
    return { count: flat.length, selectors: flat.map((f) => (f.media ? f.media + " -> " : "") + f.selector) , rules: walk2(style.sheet.cssRules, "").map(r => ({ media: r.media, selector: r.selector, props: Object.fromEntries([...Array(r.style.length)].map((_, i) => { const p = r.style[i]; return [p, r.style.getPropertyValue(p)]; })) })) };
  }, css);
});
display({ parsedRules: out.count });
const R = parse(await Bun.file("C:/Users/basam/.pi/agent/extensions/scholar/scholar.css").text());
display({ sourceRules: R.length });
// compare selector sequences and declaration presence
let seqMismatch = 0, propIssues = [];
for (let i = 0; i < R.length; i++){
  const a = R[i], b = out.rules[i];
  if (!b) { propIssues.push("no parsed rule at index " + i + " (" + a.selector + ")"); continue; }
  const na = a.selector.replace(/\s+/g, " ").trim(), nb = b.selector.replace(/\s+/g, " ").trim();
  if (na !== nb) { seqMismatch++; if (seqMismatch < 5) propIssues.push("selector mismatch @" + i + ":\n  src: " + na + "\n  dom: " + nb); }
  for (const decl of a.decls.split(";")){
    const idx = decl.indexOf(":");
    if (idx < 0) continue;
    const prop = decl.slice(0, idx).trim(), val = decl.slice(idx + 1).trim();
    if (prop.startsWith("--")) { if (!b.props[prop]) propIssues.push("custom prop dropped: " + prop + " in " + na); continue; }
    const got = b.props[prop];
    if (got === undefined || got === "") propIssues.push("declaration dropped/unknown: " + prop + ": " + val + "  in  " + na);
  }
}
display({ selectorSequenceMismatches: seqMismatch, declarationProblems: propIssues.length });
propIssues.slice(0, 20).forEach(p => console.log("  " + p));

