const geo = await tab.run(async ({ page }) => {
  await page.evaluate(() => {
    const img = document.querySelector('[data-callout="scholar-figure"] img');
    img.src = "data:image/svg+xml;utf8," + encodeURIComponent(
      '<svg xmlns="http://www.w3.org/2000/svg" width="480" height="260"><rect width="480" height="260" fill="#c8d4f0"/><path d="M0 240 L160 150 L300 200 L480 40" stroke="#3b3b6b" stroke-width="6" fill="none"/><text x="20" y="40" font-size="22" fill="#3b3b6b">f(x)</text></svg>');
    img.removeAttribute("width"); img.removeAttribute("height");
    img.style.width = "480px"; img.style.height = "auto";
  });
  await new Promise((r) => setTimeout(r, 250));
  const measure = () => {
    const frame = document.querySelector('[data-callout="scholar-figure"] .image-embed');
    const img = frame.querySelector("img");
    const f = frame.getBoundingClientRect(), i = img.getBoundingClientRect();
    const callout = document.querySelector('[data-callout="scholar-figure"]').getBoundingClientRect();
    return {
      frame: { w: +f.width.toFixed(1), h: +f.height.toFixed(1), left: +f.left.toFixed(1) },
      img: { w: +i.width.toFixed(1), h: +i.height.toFixed(1), left: +i.left.toFixed(1) },
      centeredOffset: +((i.left - f.left) - (f.right - i.right)).toFixed(2),
      frameInsideCallout: +(f.left - callout.left).toFixed(1),
      calloutWidth: +callout.width.toFixed(1),
      overflowX: document.documentElement.scrollWidth - document.documentElement.clientWidth,
    };
  };
  const light = await page.evaluate(() => { document.body.className = "theme-light"; return null; }).then(measure);
  const dark = await page.evaluate(() => { document.body.className = "theme-dark"; return null; }).then(measure);
  const paths = {};
  for (const th of ["light", "dark"]) {
    await page.evaluate((t) => { document.body.className = "theme-" + t; }, th);
    await new Promise((r) => setTimeout(r, 150));
    paths[th] = process.env.TEMP + "/scholar-css2-" + th + ".png";
    await page.screenshot({ path: paths[th], fullPage: true });
  }
  return { light, dark, paths };
});
display(geo);

