const oldCounts = new Map(); for (const r of R0){ oldCounts.set(key(r), (oldCounts.get(key(r)) || 0) + 1); }
const newDupes = [...counts].filter(([k, n]) => n > 1 && (oldCounts.get(k) || 0) <= 1).map(([k]) => k);
