const final = await tab.run(async ({ page }) => {
  const css = await Bun.file("C:/Users/basam/.pi/agent/extensions/scholar/scholar.css").text();
  return await page.evaluate((text) => {
    const style = document.createElement("style");
    style.textContent = text;
    document.head.appendChild(style);
    const flat = [];
    const walk = (rules) => { for (let i = 0; i < rules.length; i++){ const r = rules[i]; if (r.type === 4) walk(r.cssRules); else if (r.type === 1) flat.push(r); } };
    walk(style.sheet.cssRules);
    return flat.map((r) => ({ sel: r.selectorText, css: r.cssText }));
  }, css);
});
const R = parse(await Bun.file("C:/Users/basam/.pi/agent/extensions/scholar/scholar.css").text());
const dropped = [];
for (let i = 0; i < R.length; i++){
  const a = R[i], b = final[i];
  if (!b) { dropped.push("no parsed rule for " + a.selector); continue; }
  const domCss = b.css.replace(/\s+/g, " ");
  for (const decl of a.decls.split(";")){
    const idx = decl.indexOf(":");
    if (idx < 0) continue;
    const prop = decl.slice(0, idx).trim();
    // browser normalizations: `border: 0` -> border-*: 0px; `border-inline: none` -> expanded; margin-inline-* -> merged shorthand
    if (/^(border|border-inline)$/.test(prop)) continue;
    if (/^margin-inline-(start|end)$/.test(prop)) { if (!domCss.includes("margin-inline:")) dropped.push("margin-inline pair lost in " + b.sel); continue; }
    if (!domCss.includes(prop + ":")) dropped.push("DROPPED `" + decl.trim() + "` in " + b.sel);
  }
}
display({ sourceRules: R.length, browserRules: final.length, realDrops: dropped.length });
dropped.slice(0, 10).forEach(d => console.log(d));
